import { useState } from 'react';
import { BoardCodeForm } from './BoardCodeForm.tsx';
import { ReproductionControl } from './control-labels.ts';
import type { GameState } from '../game.ts';
import './control.css';
import './reproduction.css';

const SNAPSHOT_MAX_CHARACTERS = 65_536;

interface ReproductionProps {
  game: GameState;
  generation: number;
  exportSnapshot(): string;
  loadBoard(code: string): boolean;
  loadSnapshot(text: string): boolean;
  notice: string;
  paused: boolean;
  resume(): void;
}

export function Reproduction({
  game,
  generation,
  exportSnapshot,
  loadBoard,
  loadSnapshot,
  notice,
  paused,
  resume,
}: ReproductionProps) {
  const [snapshot, setSnapshot] = useState('');
  return (
    <>
      <details className="reproduction">
        <summary>{ReproductionControl.summary}</summary>
        <div className="reproduction-body">
          <BoardCodeForm code={game.boardCode} generation={generation} loadBoard={loadBoard} />
          <label htmlFor="snapshot-json">{ReproductionControl.snapshot}</label>
          <textarea
            id="snapshot-json"
            className="control"
            rows={5}
            value={snapshot}
            maxLength={SNAPSHOT_MAX_CHARACTERS}
            spellCheck={false}
            onChange={(event) => setSnapshot(event.currentTarget.value)}
          />
          <div className="control-row">
            <button type="button" className="control" onClick={() => setSnapshot(exportSnapshot())}>
              {ReproductionControl.exportSnapshot}
            </button>
            <button
              type="button"
              className="control"
              aria-describedby="load-notice"
              onClick={() => loadSnapshot(snapshot)}
            >
              {ReproductionControl.loadSnapshot}
            </button>
          </div>
        </div>
      </details>
      <div className="load-status">
        <p id="load-notice" className="load-notice">
          {notice}
        </p>
        {paused && (
          <button type="button" className="control" onClick={resume}>
            {ReproductionControl.resume}
          </button>
        )}
      </div>
    </>
  );
}
import { useRef } from 'react';
import { ReproductionControl } from './control-labels.ts';
import './control.css';
import './reproduction.css';

const BOARD_CODE_MAX_CHARACTERS = 32;
interface BoardCodeFormProps {
  code: string;
  generation: number;
  loadBoard(code: string): boolean;
}

export function BoardCodeForm({ code, generation, loadBoard }: BoardCodeFormProps) {
  const loadButton = useRef<HTMLButtonElement>(null);
  return (
    <form
      onSubmit={(event) => {
        event.preventDefault();
        const draft = new FormData(event.currentTarget).get('boardCode');
        // A loaded deal replaces the input, so focus moves to Load board. An invalid code
        // keeps focus in the draft for correction.
        if (typeof draft === 'string' && loadBoard(draft)) loadButton.current?.focus();
      }}
    >
      <label htmlFor="board-code">{ReproductionControl.board}</label>
      <div className="control-row">
        <input
          key={generation}
          id="board-code"
          className="control"
          name="boardCode"
          defaultValue={code}
          maxLength={BOARD_CODE_MAX_CHARACTERS}
          spellCheck={false}
          autoComplete="off"
        />
        <button ref={loadButton} type="submit" className="control" aria-describedby="load-notice">
          {ReproductionControl.loadBoard}
        </button>
      </div>
    </form>
  );
}
